use super::error::GitError;
use super::GitCli;
use std::fs;
use std::path::{Path, PathBuf};

pub const HOOK_BEGIN_MARKER: &str = "# BEGIN DIFFMEM HOOK";
pub const HOOK_END_MARKER: &str = "# END DIFFMEM HOOK";

pub const POST_COMMIT_SCRIPT: &str = r#"# BEGIN DIFFMEM HOOK
# Auto-generated by diffmem init. Do not edit between markers.
if command -v diffmem >/dev/null 2>&1; then
    diffmem record --post-commit >/dev/null 2>&1 || true
fi
# END DIFFMEM HOOK
"#;

pub struct HookManager<'a> {
    git: &'a GitCli,
}

impl<'a> HookManager<'a> {
    pub fn new(git: &'a GitCli) -> Self {
        Self { git }
    }

    pub fn hook_path(&self) -> Result<PathBuf, GitError> {
        let hooks_dir_str = self.git.run_git(&["rev-parse", "--git-path", "hooks"])?;
        let trimmed = hooks_dir_str.trim();
        let hooks_dir = if PathBuf::from(trimmed).is_absolute() {
            PathBuf::from(trimmed)
        } else {
            self.git.repo_root().join(trimmed)
        };
        Ok(hooks_dir.join("post-commit"))
    }

    pub fn is_installed(&self) -> Result<bool, GitError> {
        let path = self.hook_path()?;
        if !path.exists() {
            return Ok(false);
        }
        let content = fs::read_to_string(&path)?;
        Ok(content.contains(HOOK_BEGIN_MARKER))
    }

    pub fn install(&self) -> Result<bool, GitError> {
        let path = self.hook_path()?;
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }

        let content = if path.exists() {
            let existing = fs::read_to_string(&path)?;
            if existing.contains(HOOK_BEGIN_MARKER) {
                let start = existing.find(HOOK_BEGIN_MARKER).unwrap();
                let end = existing.find(HOOK_END_MARKER)
                    .map(|i| i + HOOK_END_MARKER.len())
                    .unwrap_or(existing.len());
                let mut out = String::new();
                out.push_str(&existing[..start]);
                out.push_str(POST_COMMIT_SCRIPT.trim_end());
                if end < existing.len() {
                    out.push_str(&existing[end..]);
                }
                out
            } else {
                format!("{}\n\n{}", existing.trim_end(), POST_COMMIT_SCRIPT)
            }
        } else {
            format!("#!/bin/sh\n{}", POST_COMMIT_SCRIPT)
        };

        // Write using explicit LF line endings for POSIX / MSYS bash compatibility
        let lf_content = content.replace("\r\n", "\n");
        fs::write(&path, lf_content.as_bytes())?;

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&path, fs::Permissions::from_mode(0o755))?;
        }

        Ok(true)
    }

    pub fn uninstall(&self) -> Result<bool, GitError> {
        let path = self.hook_path()?;
        if !path.exists() {
            return Ok(false);
        }
        let existing = fs::read_to_string(&path)?;
        if !existing.contains(HOOK_BEGIN_MARKER) {
            return Ok(false);
        }

        let start = existing.find(HOOK_BEGIN_MARKER).unwrap();
        let end = existing.find(HOOK_END_MARKER)
            .map(|i| i + HOOK_END_MARKER.len())
            .unwrap_or(existing.len());

        let mut out = String::new();
        out.push_str(&existing[..start]);
        if end < existing.len() {
            out.push_str(&existing[end..]);
        }

        let trimmed = out.trim();
        if trimmed.is_empty() || trimmed == "#!/bin/sh" {
            let _ = fs::remove_file(&path);
        } else {
            let lf = format!("{}\n", trimmed).replace("\r\n", "\n");
            fs::write(&path, lf.as_bytes())?;
        }

        Ok(true)
    }
}

pub fn install_post_commit_hook(repo: &Path) -> Result<bool, GitError> {
    let git = GitCli::new(repo);
    let manager = HookManager::new(&git);
    manager.install()
}

pub fn uninstall_post_commit_hook(repo: &Path) -> Result<bool, GitError> {
    let git = GitCli::new(repo);
    let manager = HookManager::new(&git);
    manager.uninstall()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::process::Command;
    use tempfile::tempdir;

    #[test]
    fn test_hook_install_and_uninstall() {
        let dir = tempdir().unwrap();
        let status = Command::new("git")
            .arg("init")
            .current_dir(dir.path())
            .status()
            .unwrap();
        assert!(status.success());

        let git = GitCli::new(dir.path());
        let manager = HookManager::new(&git);

        assert!(!manager.is_installed().unwrap());

        // Install
        assert!(manager.install().unwrap());
        assert!(manager.is_installed().unwrap());

        // Verify content and LF line endings
        let hook_file = manager.hook_path().unwrap();
        assert!(hook_file.exists());
        let content = fs::read_to_string(&hook_file).unwrap();
        assert!(content.contains(HOOK_BEGIN_MARKER));
        assert!(content.contains(HOOK_END_MARKER));
        assert!(!content.contains("\r\n"), "Hook must use strict LF line endings");

        // Idempotent install
        assert!(manager.install().unwrap());
        let content2 = fs::read_to_string(&hook_file).unwrap();
        assert_eq!(content, content2, "Re-install must be idempotent");

        // Uninstall
        assert!(manager.uninstall().unwrap());
        assert!(!manager.is_installed().unwrap());
    }
}
